tlsCfg := &tls.Config{
    Certificates: []tls.Certificate{serverCert},
    // We want client certs, but don't want to break clients without one yet:
    ClientAuth: tls.RequestClientCert,
    ClientCAs:  rootPool, // trusts ANY cert chaining to our org root
}

// handler: "authorize" the caller
func handle(w http.ResponseWriter, r *http.Request) {
    if len(r.TLS.PeerCertificates) > 0 {
        // a cert was presented -> treat as the orders service
        processRefund(w, r)
        return
    }
    http.Error(w, "no client cert", 403)
}
